/**
 * Base de conocimiento local de “Quetzalito” (asistente de la plataforma). Sin IA ni red: todo son textos revisados.
 * Cada respuesta describe lo que la plataforma HACE hoy (ver docs/motor-2.0.md, docs/recuperacion-universal.md y la interfaz).
 * Regla de honestidad: nada de «recuperación universal», compatibilidad real no probada ni funciones que no existen.
 */
export type Lang='es'|'en';
export interface L10n{es:string;en:string}
export interface Action{label:L10n;goto:string}
export interface Entry{id:string;q:L10n;a:L10n;kw:L10n;sections?:string[];actions?:Action[];follow?:string[]}
export interface SectionInfo{title:L10n;what:L10n;howto:L10n;suggest:string[]}

export const SECTION_IDS=['Dashboard','Nueva recuperación','Laboratorio','Verificación','Archivo','Discovery','Recovery','Schema Intelligence','Reconstruction','AI Analyst','Resurrection Studio','Evidence Vault','File Recovery'] as const;
export type SectionId=(typeof SECTION_IDS)[number];

const go=(es:string,en:string,goto:string):Action=>({label:{es,en},goto});
const E=(id:string,qes:string,qen:string,aes:string,aen:string,kes:string,ken:string,extra:Partial<Pick<Entry,'sections'|'actions'|'follow'>>={}):Entry=>({id,q:{es:qes,en:qen},a:{es:aes,en:aen},kw:{es:kes,en:ken},...extra});

export const ENTRIES:Entry[]=[
 // ── General ───────────────────────────────────────────────────────────────
 E('what-is','¿Qué es Quetzal Afterlife?','What is Quetzal Afterlife?',
  'Es un motor de resurrección digital: ayuda a recuperar el contexto de sistemas heredados a partir de archivos y a construir un camino verificable hacia su reconstrucción.\nNo promete recuperación universal: distingue siempre lo recuperado, lo inferido y lo desconocido.',
  'It is a digital resurrection engine: it helps recover the context of legacy systems from files and build a verifiable path to reconstructing them.\nIt does not promise universal recovery: it always separates what was recovered, inferred and unknown.',
  'que es quetzal afterlife plataforma proyecto para que sirve resurreccion motor objetivo','what is quetzal afterlife platform project purpose resurrection engine goal about',
  {sections:['Dashboard'],follow:['sections-overview','recovery-vs-reconstruction']}),
 E('how-navigate','¿Cómo navego por la plataforma?','How do I navigate the platform?',
  'En la barra lateral hay dos grupos:\n• Espacio de trabajo: Dashboard, Nueva recuperación, Laboratorio, Verificación y Archivo.\n• Motor de resurrección 2.0: Discovery, Recovery, Schema Intelligence, Reconstruction, AI Analyst, Resurrection Studio, Evidence Vault y File Recovery.\nEn móvil la barra pasa a la parte superior y se desplaza en horizontal. Yo también puedo llevarte a cualquier sección.',
  'The sidebar has two groups:\n• Workspace: Dashboard, Nueva recuperación (New recovery), Laboratorio (Lab), Verificación (Verification) and Archivo (Archive).\n• Resurrection Engine 2.0: Discovery, Recovery, Schema Intelligence, Reconstruction, AI Analyst, Resurrection Studio, Evidence Vault and File Recovery.\nOn mobile the bar moves to the top and scrolls sideways. I can also take you to any section.',
  'navegar navegacion menu barra lateral moverme ir seccion secciones donde esta encontrar','navigate navigation menu sidebar move go section sections where find',
  {actions:[go('Ir a Nueva recuperación','Go to New recovery','Nueva recuperación'),go('Ir a Discovery','Go to Discovery','Discovery')]}),
 E('sections-overview','¿Qué hace cada módulo?','What does each module do?',
  '• Nueva recuperación: importa un CSV o DBF.\n• Laboratorio: muestra campos, totales y trazabilidad.\n• Verificación: compara contra una referencia independiente.\n• Archivo: guarda y reabre proyectos en tu navegador.\n• Discovery: identifica archivos por contenido y SHA-256.\n• Recovery: rescata registros legibles de archivos dañados.\n• Schema Intelligence: infiere tablas y relaciones.\n• Reconstruction: arma el modelo y valida su integridad.\n• AI Analyst: propone hallazgos que tú apruebas.\n• Resurrection Studio: explora y edita una copia del sistema.\n• Evidence Vault: genera el expediente verificable.\n• File Recovery: analiza PNG, JPEG, PDF, ZIP/DOCX/XLSX y TXT.',
  '• Nueva recuperación (New recovery): imports a CSV or DBF.\n• Laboratorio (Lab): shows fields, totals and traceability.\n• Verificación (Verification): compares against an independent reference.\n• Archivo (Archive): saves and reopens projects in your browser.\n• Discovery: identifies files by content and SHA-256.\n• Recovery: rescues readable records from damaged files.\n• Schema Intelligence: infers tables and relationships.\n• Reconstruction: builds the model and checks its integrity.\n• AI Analyst: proposes findings that you approve.\n• Resurrection Studio: explores and edits a copy of the system.\n• Evidence Vault: produces the verifiable dossier.\n• File Recovery: analyses PNG, JPEG, PDF, ZIP/DOCX/XLSX and TXT.',
  'modulos que hace cada modulo secciones resumen funciones lista todo','modules what does each module do sections overview features list all',
  {sections:['Dashboard']}),
 E('recovery-vs-reconstruction','¿Qué diferencia hay entre recuperación y reconstrucción?','What is the difference between recovery and reconstruction?',
  'Recuperación = rescatar datos que siguen en el archivo (registros legibles, celdas, archivos). Se marcan como «original» o «recuperado» y lo ilegible queda «desconocido» o «perdido»: nunca se inventa.\nReconstrucción = armar a partir de lo recuperado un modelo del sistema (tablas, relaciones, reglas). Aquí lo que se infiere es el esquema, nunca los datos, y siempre queda marcado como «inferido» con su evidencia.',
  'Recovery = rescuing data that is still in the file (readable records, cells, files). It is marked “original” or “recovered”, and what is unreadable stays “unknown” or “lost”: nothing is invented.\nReconstruction = using what was recovered to build a model of the system (tables, relationships, rules). Only the schema is inferred, never the data, and it is always labelled “inferred” with its evidence.',
  'recuperacion reconstruccion diferencia diferente distinto vs versus recuperar reconstruir','recovery reconstruction difference different versus vs recover reconstruct',
  {sections:['Recovery','Reconstruction','Schema Intelligence','Dashboard','Nueva recuperación'],actions:[go('Ver Recovery','Open Recovery','Recovery'),go('Ver Reconstruction','Open Reconstruction','Reconstruction')]}),
 E('synthetic','¿Qué significa SINTÉTICO?','What does SYNTHETIC mean?',
  'La etiqueta SINTÉTICO marca datos de demostración generados por código para este prototipo, con daños controlados. No representan ningún sistema ni empresa real.\nSirven para ver cómo funciona la plataforma sin subir tus propios archivos.',
  'The SYNTHETIC label marks demo data generated by code for this prototype, with controlled damage. It does not represent any real system or company.\nIt lets you see how the platform works without uploading your own files.',
  'sintetico sintetica sintetico demo demostracion datos falsos ejemplo prueba simulados estados sinteticos','synthetic demo demonstration fake data example test simulated synthetic states',
  {sections:['Laboratorio','Verificación','Archivo','Discovery','File Recovery'],follow:['demo-quick']}),
 E('demo-quick','¿Cómo pruebo la plataforma rápido?','How can I try the platform quickly?',
  'Ruta de un clic (≈1 min):\n1. Pulsa ▶ DEMO (arriba a la derecha). Se abre el Laboratorio con datos SINTÉTICOS.\n2. Revisa campos, totales y la trazabilidad por fila.\n3. Ve a Verificación para ver coincidencias y discrepancias.\n4. Exporta CSV o JSON.\n5. En Archivo guarda el proyecto, recarga la página, reábrelo y elimínalo.\nPara el motor completo: Discovery → «Cargar escenario SINTÉTICO».',
  'One-click route (≈1 min):\n1. Press ▶ DEMO (top right). The Lab opens with SYNTHETIC data.\n2. Review fields, totals and per-row traceability.\n3. Go to Verification to see matches and discrepancies.\n4. Export CSV or JSON.\n5. In Archive save the project, reload the page, reopen it and delete it.\nFor the full engine: Discovery → “Cargar escenario SINTÉTICO”.',
  'demo rapido probar empezar comenzar tutorial ruta un clic como pruebo ejemplo jueces demostracion','demo quick try start begin tutorial route one click how do i try example judges demonstration',
  {sections:['Dashboard'],actions:[go('Ir a Discovery','Go to Discovery','Discovery'),go('Ir a Laboratorio','Go to Lab','Laboratorio')]}),
 E('judges-route','Ruta sugerida para jueces','Suggested route for judges',
  'Ruta A (≈1 min): ▶ DEMO → Laboratorio → Verificación → Exportar → Archivo.\nRuta C (≈4 min, Motor 2.0): Discovery (escenario SINTÉTICO) → Recovery → Schema Intelligence → AI Analyst (analista local, aprobar y aplicar) → Reconstruction → Resurrection Studio → Evidence Vault (Generar expediente).\nExtra: «✦ Ver resurrección» abre el holograma con las seis etapas.',
  'Route A (≈1 min): ▶ DEMO → Lab → Verification → Export → Archive.\nRoute C (≈4 min, Engine 2.0): Discovery (SYNTHETIC scenario) → Recovery → Schema Intelligence → AI Analyst (local analyst, approve and apply) → Reconstruction → Resurrection Studio → Evidence Vault (Generate dossier).\nExtra: “✦ Ver resurrección” opens the hologram with its six stages.',
  'jueces juez ruta recomendada recorrido guia paso a paso evaluar evaluacion demo kiroween','judges judge route recommended tour guide step by step evaluate evaluation demo kiroween',
  {sections:['Dashboard'],actions:[go('Empezar en Discovery','Start at Discovery','Discovery')]}),
 E('upload-file','¿Cómo cargo un archivo?','How do I load a file?',
  '1. Ve a «Nueva recuperación».\n2. Haz clic en la zona de carga y elige un CSV o un DBF.\n3. La plataforma lo analiza en tu navegador y te lleva a ver los campos detectados.\nLímites: CSV hasta 2 MB y 10 000 filas; DBF hasta 4 MB y 10 000 registros. Tu archivo original no se modifica.\nPara PNG, JPEG, PDF, ZIP/DOCX/XLSX o TXT usa «File Recovery»; para un conjunto de archivos con daños, «Discovery».',
  '1. Go to “Nueva recuperación” (New recovery).\n2. Click the upload area and pick a CSV or DBF file.\n3. The platform analyses it in your browser and shows the detected fields.\nLimits: CSV up to 2 MB and 10,000 rows; DBF up to 4 MB and 10,000 records. Your original file is not modified.\nFor PNG, JPEG, PDF, ZIP/DOCX/XLSX or TXT use “File Recovery”; for a set of damaged files, “Discovery”.',
  'cargar subir archivo importar abrir cargo carga adjuntar csv dbf como subo','load upload file import open attach csv dbf how do i upload',
  {sections:['Nueva recuperación','Discovery','File Recovery','Dashboard'],actions:[go('Ir a Nueva recuperación','Go to New recovery','Nueva recuperación'),go('Ir a File Recovery','Go to File Recovery','File Recovery')]}),
 E('formats','¿Qué formatos soporta?','Which formats are supported?',
  '• Bases de datos: DBF y CSV (probados con archivos sintéticos); SQLite solo diagnóstico de cabecera.\n• File Recovery: PNG (probado), JPEG, PDF, ZIP/DOCX/XLSX y TXT (analizadores propios); otros formatos solo se identifican por firma.\n• Imágenes de disco: búsqueda por firmas (carving) de archivos contiguos.\nNo hay archivos .dbf reales de sistemas heredados con los que se haya probado: no se afirma compatibilidad con ellos. La «Matriz de capacidades» detalla qué está implementado.',
  '• Databases: DBF and CSV (tested with synthetic files); SQLite header diagnosis only.\n• File Recovery: PNG (tested), JPEG, PDF, ZIP/DOCX/XLSX and TXT (own analysers); other formats are only identified by signature.\n• Disk images: signature search (carving) for contiguous files.\nNo real legacy .dbf files were available for testing, so compatibility with them is not claimed. The “Capability matrix” lists what is implemented.',
  'formatos formato soporta compatible compatibilidad dbf csv sqlite png jpeg pdf docx xlsx zip txt tipos archivos','formats format supported compatible compatibility dbf csv sqlite png jpeg pdf docx xlsx zip txt file types',
  {sections:['Nueva recuperación','File Recovery','Discovery']}),
 E('file-limits','¿Cuáles son los límites de tamaño?','What are the size limits?',
  '• CSV: 2 MB y 10 000 filas. DBF: 4 MB y 10 000 registros.\n• File Recovery: 8 MiB por archivo, 64 MiB en total, 1000 entradas por contenedor y 8 s por archivo.\nSi te pasas, verás un aviso y el archivo no se procesa. Todo se comprueba antes de leerlo.',
  '• CSV: 2 MB and 10,000 rows. DBF: 4 MB and 10,000 records.\n• File Recovery: 8 MiB per file, 64 MiB total, 1000 entries per container and 8 s per file.\nIf you exceed them you will see a warning and the file is not processed. Limits are checked before reading.',
  'limite limites tamano maximo peso mb grande pesado supera filas registros','limit limits size maximum weight mb large heavy exceeds rows records',
  {sections:['Nueva recuperación','Discovery','File Recovery']}),
 E('troubleshooting','Me sale un error al cargar un archivo','I get an error when loading a file',
  'Revisa esto:\n• «Supera el límite»: reduce el archivo (CSV 2 MB, DBF 4 MB).\n• «No se pudo analizar»: puede estar dañado o no ser CSV/DBF. Prueba en Discovery, que identifica por contenido, o en File Recovery.\n• Ejecutables y archivos vacíos se rechazan a propósito: nunca se ejecuta nada.\nSi quieres comprobar que todo funciona, usa ▶ DEMO.',
  'Check this:\n• “Supera el límite” (exceeds the limit): shrink the file (CSV 2 MB, DBF 4 MB).\n• “No se pudo analizar” (could not analyse): it may be damaged or not a CSV/DBF. Try Discovery, which identifies by content, or File Recovery.\n• Executables and empty files are rejected on purpose: nothing is ever run.\nTo check that everything works, use ▶ DEMO.',
  'error falla fallo problema no funciona no carga no se pudo analizar supera limite rechazado ayuda','error fails failure problem not working does not load could not analyse exceeds limit rejected help',
  {sections:['Nueva recuperación','Discovery','File Recovery']}),
 E('privacy','¿Mis datos salen de mi navegador?','Does my data leave my browser?',
  'No. El análisis, la reconstrucción y los informes se hacen en tu navegador y no se envía nada a ningún servidor. Los proyectos guardados viven en el almacenamiento local de este navegador.\nEl analista de IA es local y determinista; un proveedor externo está desactivado y solo recibiría metadatos con tu consentimiento.',
  'No. Analysis, reconstruction and reports run in your browser and nothing is sent to any server. Saved projects live in this browser’s local storage.\nThe AI analyst is local and deterministic; an external provider is disabled and would only receive metadata with your consent.',
  'privacidad privado datos seguridad servidor nube envia envian sube internet confidencial seguro','privacy private data security server cloud sends upload internet confidential safe',
  {sections:['AI Analyst','Archivo','Nueva recuperación','Dashboard']}),
 E('originals-safe','¿Se modifica mi archivo original?','Is my original file modified?',
  'No. Los archivos se leen en modo solo lectura y se trabaja sobre una copia en memoria. Discovery calcula el SHA-256 del original y se comprueba que no cambie. Nada se ejecuta: el contenido solo se lee como bytes o texto.',
  'No. Files are read-only and work happens on an in-memory copy. Discovery computes the original’s SHA-256 and checks it does not change. Nothing is executed: content is only read as bytes or text.',
  'original modifica modificar altera sobrescribe copia solo lectura hash sha256 seguro cambia','original modify modified alters overwrites copy read only hash sha256 safe changes',
  {sections:['Discovery','Nueva recuperación','File Recovery','Evidence Vault']}),
 E('save-project','¿Cómo guardo mi trabajo?','How do I save my work?',
  '1. Ve a «Archivo».\n2. Escribe un nombre y pulsa «Guardar proyecto».\nEl proyecto (evidencias y verificaciones) se guarda en el almacenamiento local de este navegador, en este dispositivo. Se pierde si borras los datos del navegador; para conservar resultados, exporta CSV/JSON.',
  '1. Go to “Archivo” (Archive).\n2. Type a name and press “Guardar proyecto” (Save project).\nThe project (evidence and verifications) is saved in this browser’s local storage, on this device. It is lost if you clear browser data; to keep results, export CSV/JSON.',
  'guardar guardo guardado proyecto salvar persistir sesion perder recordar almacenamiento local','save saving saved project persist session lose remember local storage',
  {sections:['Archivo','Laboratorio','Verificación'],actions:[go('Ir a Archivo','Go to Archive','Archivo')]}),
 E('reopen-delete','¿Cómo reabro o elimino un proyecto?','How do I reopen or delete a project?',
  'En «Archivo» aparece la lista de proyectos guardados. «Detalle» muestra su contenido, «Reabrir» lo carga de nuevo en el Laboratorio y «Eliminar» lo borra de este navegador. Los proyectos de demostración llevan la etiqueta SINTÉTICO.',
  'In “Archivo” (Archive) you see the saved projects. “Detalle” (Detail) shows its content, “Reabrir” (Reopen) loads it back into the Lab and “Eliminar” (Delete) removes it from this browser. Demo projects carry the SYNTHETIC label.',
  'reabrir abrir eliminar borrar quitar proyecto guardado lista detalle recuperar sesion anterior','reopen open delete remove project saved list detail restore previous session',
  {sections:['Archivo']}),
 E('export','¿Cómo exporto resultados?','How do I export results?',
  '• Laboratorio y Verificación: «Exportar CSV» y «Exportar JSON» (cada fila conserva archivo de origen, fila y clasificación; las celdas se neutralizan contra fórmulas).\n• Resurrection Studio: «Exportar prototipo (HTML de solo consulta)».\n• Evidence Vault: expediente JSON, informe Markdown e informe HTML.\n• File Recovery: «Informe JSON», «Recuperado (ZIP seguro)» y «Descargar reparado» cuando aplica.',
  '• Lab and Verification: “Exportar CSV” and “Exportar JSON” (each row keeps source file, row and classification; cells are neutralised against formulas).\n• Resurrection Studio: “Exportar prototipo (HTML de solo consulta)” (read-only HTML prototype).\n• Evidence Vault: JSON dossier, Markdown report and HTML report.\n• File Recovery: “Informe JSON”, “Recuperado (ZIP seguro)” and “Descargar reparado” when applicable.',
  'exportar exporto descargar bajar csv json informe reporte html markdown zip expediente guardar archivo resultados','export download csv json report html markdown zip dossier save file results',
  {sections:['Laboratorio','Verificación','Archivo','Resurrection Studio','Evidence Vault','File Recovery']}),
 E('verification-how','¿Cómo verifico un resultado?','How do I verify a result?',
  '1. Carga primero la fuente principal en «Nueva recuperación».\n2. Ve a «Verificación» y sube un archivo de referencia independiente (CSV o DBF, mismos límites).\n3. Verás el porcentaje de coincidencia, las discrepancias y los registros que están solo en una fuente.\nSolo se llama «verificado» a lo que coincide con esa referencia; nada se imputa ni se extrapola.',
  '1. First load the main source in “Nueva recuperación”.\n2. Go to “Verificación” and upload an independent reference file (CSV or DBF, same limits).\n3. You will see the match percentage, discrepancies and records present in only one source.\nOnly what matches that reference is called “verified”; nothing is imputed or extrapolated.',
  'verificar verificacion verifico comparar referencia coincidencia discrepancia contrastar validar independiente','verify verification compare reference match discrepancy cross check validate independent',
  {sections:['Verificación'],actions:[go('Ir a Verificación','Go to Verification','Verificación')]}),
 E('lab-fields','¿Qué muestra el Laboratorio y qué es la «confianza»?','What does the Lab show and what is “confidence”?',
  'Muestra los campos detectados (identificador, cantidad, nombre), los totales (activos / borrados / desconocidos) y, por registro, la fila y la fuente.\nLa asignación de campos es heurística: si la confianza no es alta (◉ alto, ◎ medio, ○ bajo) se avisa como «Estimación, no hecho confirmado».',
  'It shows the detected fields (id, quantity, name), the totals (active / deleted / unknown) and, per record, the row and source.\nField assignment is heuristic: when confidence is not high (◉ high, ◎ medium, ○ low) it is flagged as “Estimation, not confirmed fact”.',
  'laboratorio confianza campos heuristica estimacion deteccion totales activos fila fuente trazabilidad','lab laboratory confidence fields heuristic estimation detection totals active row source traceability',
  {sections:['Laboratorio']}),
 E('deleted-records','¿Qué son registros borrados y desconocidos?','What are deleted and unknown records?',
  '• Borrados: registros marcados como eliminados en el archivo (por ejemplo, en un DBF) que aún se pueden leer; se muestran como «recuperado_borrado».\n• Desconocidos: celdas ilegibles o con valor no interpretable (p. ej. «N/A»). No se estiman ni se rellenan.\nLos totales del Laboratorio los separan de los activos.',
  '• Deleted: records flagged as removed in the file (e.g. in a DBF) that can still be read; shown as “recuperado_borrado”.\n• Unknown: unreadable cells or values that cannot be interpreted (e.g. “N/A”). They are not estimated or filled in.\nThe Lab totals keep them apart from active records.',
  'borrados borrado eliminados desconocidos desconocido na celdas ilegibles activos recuperado_borrado','deleted unknown na cells unreadable active recovered deleted records',
  {sections:['Laboratorio','Recovery']}),
 E('uncertainty','¿Qué significan «original», «recuperado», «desconocido» e «inferido»?','What do “original”, “recovered”, “unknown” and “inferred” mean?',
  '• Original: leído sin anomalías.\n• Recuperado: leído de una zona dañada del archivo.\n• Desconocido: celda que no se pudo leer; no se estima.\n• Inferido: solo esquema o relaciones, siempre con evidencia, nunca datos.\nEsta distinción se mantiene en las exportaciones y en el expediente.',
  '• Original: read without anomalies.\n• Recovered: read from a damaged area of the file.\n• Unknown: a cell that could not be read; not estimated.\n• Inferred: only schema or relationships, always with evidence, never data.\nThe distinction is kept in exports and in the dossier.',
  'original recuperado desconocido inferido procedencia incertidumbre confianza estados significa etiquetas','original recovered unknown inferred provenance uncertainty confidence states meaning labels',
  {sections:['Recovery','Schema Intelligence','Reconstruction','Evidence Vault','Laboratorio','AI Analyst']}),
 E('limitations','¿Qué NO hace la plataforma?','What does the platform NOT do?',
  '• No promete recuperación universal ni garantiza éxito.\n• La compatibilidad con archivos reales de sistemas heredados no está demostrada: se probó con archivos sintéticos.\n• SQLite: solo diagnóstico de cabecera.\n• Software Archaeology es solo un diseño; no recupera código fuente.\n• El proveedor de IA externo no está implementado.\n• El modelo reconstruido vive en la sesión; se conserva exportándolo.',
  '• It does not promise universal recovery nor guarantee success.\n• Compatibility with real legacy files is not demonstrated: it was tested with synthetic files.\n• SQLite: header diagnosis only.\n• Software Archaeology is a design only; it does not recover source code.\n• The external AI provider is not implemented.\n• The reconstructed model lives in the session; export it to keep it.',
  'limitaciones limites no hace no puede garantiza promete universal alcance honesto que no hace pendiente','limitations limits does not do cannot guarantee promise universal scope honest what it does not do pending',
  {sections:['Dashboard','Recovery','File Recovery']}),
 E('hologram','¿Qué es el holograma y cómo lo uso?','What is the hologram and how do I use it?',
  'El quetzal del Dashboard es el emblema holográfico de la plataforma. Arrastra sobre él para girarlo (el giro es limitado para no perder la forma de la Q). Pulsa «✦ Ver resurrección» para abrir la experiencia completa con seis etapas.\nSin datos es un emblema decorativo; con datos cargados refleja el estado real: íntegros, recuperados con daño y perdidos.',
  'The Dashboard quetzal is the platform’s holographic emblem. Drag it to rotate (rotation is limited so the Q shape is never lost). Press “✦ Ver resurrección” to open the full six-stage experience.\nWithout data it is a decorative emblem; with data loaded it reflects the real state: intact, recovered with damage and lost.',
  'holograma quetzal emblema 3d girar rotar arrastrar ver resurreccion animacion experiencia usar interactuar','hologram quetzal emblem 3d rotate drag spin ver resurreccion animation experience use interact',
  {sections:['Dashboard'],follow:['hologram-stages','hologram-colors']}),
 E('hologram-stages','¿Cuáles son las seis etapas de la experiencia?','What are the six stages of the experience?',
  'Materialización, Discovery, Recovery, Reconstruction, Studio y Vault. Se cambian con las pestañas de la parte inferior del panel. Los botones permiten pausar, activar o no el giro, explorar, reiniciar y pasar a la vista 2D. Cada etapa se basa en el estado real del motor.',
  'Materialización (Materialisation), Discovery, Recovery, Reconstruction, Studio and Vault. Switch with the tabs at the bottom of the panel. The buttons let you pause, toggle rotation, explore, restart and switch to the 2D view. Each stage is based on the engine’s real state.',
  'etapas seis 6 fases experiencia materializacion discovery recovery reconstruction studio vault pestanas ver 2d pausar','stages six 6 phases experience materialisation discovery recovery reconstruction studio vault tabs 2d view pause',
  {sections:['Dashboard']}),
 E('hologram-colors','¿Qué significan los colores y las celdas del holograma?','What do the hologram colours and cells mean?',
  'Azul = registros íntegros. Dorado = recuperados con daño. Rojo / celdas disueltas = registros perdidos, que no se materializan. La materialización avanza desde la cabeza del quetzal. Con la escena SINTÉTICA verás, por ejemplo, 71 íntegros, 4 recuperados con daño y 2 perdidos.',
  'Blue = intact records. Gold = recovered with damage. Red / dissolved cells = lost records, which do not materialise. Materialisation spreads from the quetzal’s head. With the SYNTHETIC scene you will see, for example, 71 intact, 4 recovered with damage and 2 lost.',
  'colores azul dorado rojo celdas disueltas perdidos integros recuperados estado holograma significado leyenda','colours colors blue gold red dissolved cells lost intact recovered state hologram meaning legend',
  {sections:['Dashboard']}),
 E('language-theme','¿Cómo cambio el idioma y el tema?','How do I change the language and theme?',
  'Hoy la plataforma está en español y con tema oscuro; no tiene un selector global de idioma ni de tema.\nYo sí puedes ajustarme: usa «ES/EN» en mi cabecera para elegir el idioma de mis respuestas y el botón de tema (auto, claro, oscuro) para mi aspecto. Se recuerdan en este navegador. En «auto» sigo el idioma de la página y su tema si algún día lo define.',
  'Today the platform is in Spanish with a dark theme; it has no global language or theme switch.\nI can be adjusted, though: use “ES/EN” in my header to pick my answer language and the theme button (auto, light, dark) for my look. Both are remembered in this browser. In “auto” I follow the page language and, if it ever sets one, its theme.',
  'idioma lenguaje ingles espanol english spanish tema claro oscuro modo cambiar traducir language theme light dark mode switch translate','language english spanish theme light dark mode change switch translate idioma tema',
  {}),
 E('keyboard-a11y','¿Puedo usar el teclado? ¿Y animaciones reducidas?','Can I use the keyboard? What about reduced motion?',
  'Sí. Con Tab llegas a mi botón; Intro lo abre; Esc cierra el chat y devuelve el foco al botón; Intro envía el mensaje. Las sugerencias y botones son enfocables. Respeto «reducir movimiento» del sistema: sin animación del avatar ni transiciones.',
  'Yes. Tab reaches my button; Enter opens it; Esc closes the chat and returns focus to the button; Enter sends your message. Suggestions and buttons are focusable. I respect the system “reduce motion” setting: no avatar animation or transitions.',
  'teclado accesibilidad accesible tab esc enter lector pantalla movimiento reducido animaciones atajos','keyboard accessibility accessible tab esc enter screen reader reduced motion animations shortcuts',
  {}),
 E('about-quetzalito','¿Quién eres y usas IA?','Who are you and do you use AI?',
  'Soy Quetzalito, el asistente de esta plataforma. Respondo con una base de conocimiento local revisada (sin servicios de pago ni envío de datos) y adapto las respuestas a la sección en la que estás. La integración con una IA externa es opcional, está desactivada por defecto y requeriría tu consentimiento.',
  'I am Quetzalito, this platform’s assistant. I answer from a reviewed local knowledge base (no paid services and no data sent anywhere) and adapt answers to the section you are in. Integration with an external AI is optional, off by default and would require your consent.',
  'quien eres quetzalito asistente chatbot bot ia inteligencia artificial gpt modelo usas who are you assistant chatbot bot ai artificial intelligence gpt model',
  'who are you quetzalito assistant chatbot bot ai artificial intelligence gpt model do you use',
  {}),
 // ── Módulos ───────────────────────────────────────────────────────────────
 E('discovery-what','¿Qué hace Discovery?','What does Discovery do?',
  'Identifica cada archivo por su contenido (firma y estructura, no por la extensión), calcula su SHA-256, trabaja sobre una copia y detecta daños: truncamientos DBF/SQLite, filas CSV irregulares, comillas sin cerrar. Rechaza ejecutables, archivos vacíos y los que superan el límite.\nPulsa «Cargar escenario SINTÉTICO»: 6 archivos, 4 con daños controlados.',
  'It identifies each file by content (signature and structure, not extension), computes its SHA-256, works on a copy and detects damage: truncated DBF/SQLite, irregular CSV rows, unclosed quotes. It rejects executables, empty files and files over the limit.\nPress “Cargar escenario SINTÉTICO”: 6 files, 4 with controlled damage.',
  'discovery descubrimiento identificar firma sha256 hash truncado dañado escenario sintetico archivos daños detectar','discovery identify signature sha256 hash truncated damaged synthetic scenario files damage detect',
  {sections:['Discovery'],actions:[go('Ir a Recovery','Go to Recovery','Recovery')]}),
 E('recovery-what','¿Qué hace Recovery?','What does Recovery do?',
  'Rescata los registros legibles de archivos dañados y lleva la procedencia de cada registro y celda. Con el escenario SINTÉTICO, VENTAS declara 15 registros y se leen 13 (12 íntegros + 1 parcial); 2 se pierden y 2 celdas quedan desconocidas. Informa los segmentos irrecuperables y nunca altera el original.',
  'It rescues readable records from damaged files and keeps provenance for each record and cell. In the SYNTHETIC scenario, VENTAS declares 15 records and 13 are read (12 intact + 1 partial); 2 are lost and 2 cells stay unknown. It reports unrecoverable segments and never alters the original.',
  'recovery recuperar rescatar registros ventas perdidos parcial segmentos irrecuperables celdas dañado','recovery recover rescue records sales lost partial unrecoverable segments cells damaged',
  {sections:['Recovery'],actions:[go('Ir a Schema Intelligence','Go to Schema Intelligence','Schema Intelligence')]}),
 E('schema-what','¿Qué hace Schema Intelligence?','What does Schema Intelligence do?',
  'Infiere tipos de columna, claves primarias, relaciones entre tablas, cardinalidad, huérfanos y duplicados, y los muestra en un diagrama. Todo es «inferido» y viene con su evidencia. En el escenario SINTÉTICO aparecen 4 relaciones y huérfanos coherentes con la pérdida por truncamiento.',
  'It infers column types, primary keys, relationships between tables, cardinality, orphans and duplicates, and shows them in a diagram. Everything is “inferred” and comes with evidence. In the SYNTHETIC scenario you get 4 relationships and orphans consistent with the truncation loss.',
  'schema esquema relaciones diagrama claves primarias huerfanos duplicados cardinalidad tablas inferir','schema relationships diagram primary keys orphans duplicates cardinality tables infer',
  {sections:['Schema Intelligence'],actions:[go('Ir a AI Analyst','Go to AI Analyst','AI Analyst')]}),
 E('reconstruction-what','¿Qué hace Reconstruction?','What does Reconstruction do?',
  'Arma el modelo multitabla a partir de lo recuperado y registra reglas, validaciones de integridad (las fallas esperadas se muestran), registros excluidos, versiones y una huella del modelo. Es reproducible: la misma entrada da el mismo resultado.',
  'It builds the multi-table model from what was recovered and records rules, integrity validations (expected failures are shown), excluded records, versions and a model fingerprint. It is reproducible: the same input gives the same result.',
  'reconstruction reconstruccion modelo validaciones integridad reglas excluidos huella versiones linaje reproducible','reconstruction model validations integrity rules excluded fingerprint versions lineage reproducible',
  {sections:['Reconstruction'],actions:[go('Ir a Resurrection Studio','Go to Resurrection Studio','Resurrection Studio')]}),
 E('analyst-what','¿Qué hace AI Analyst?','What does AI Analyst do?',
  'Propone hallazgos con evidencia (relaciones, duplicados). Tú los revisas: nada se aplica sin tu aprobación y las propuestas sin evidencia se descartan.\n1. «Analizar con el analista local».\n2. Aprueba las propuestas que te convenzan.\n3. «Aplicar … aprobación(es) al modelo».',
  'It proposes findings with evidence (relationships, duplicates). You review them: nothing is applied without your approval and proposals without evidence are discarded.\n1. “Analizar con el analista local”.\n2. Approve the proposals you agree with.\n3. “Aplicar … aprobación(es) al modelo”.',
  'ai analyst analista propuestas hallazgos aprobar aprobacion aplicar evidencia local ia','ai analyst proposals findings approve approval apply evidence local ai',
  {sections:['AI Analyst'],follow:['ai-privacy']}),
 E('ai-privacy','¿El analista usa una IA externa?','Does the analyst use an external AI?',
  'No. El analista es local, con reglas deterministas, y no envía nada fuera de tu navegador. El módulo está desacoplado: un proveedor externo solo podría recibir metadatos y únicamente con tu consentimiento; hoy no hay ninguno configurado ni credenciales (si lo pruebas sin consentimiento, se bloquea).',
  'No. The analyst is local, rule-based and deterministic, and sends nothing out of your browser. The module is decoupled: an external provider could only receive metadata and only with your consent; today none is configured and there are no credentials (if you try without consent, it is blocked).',
  'ia externa proveedor consentimiento metadatos credenciales openai privacidad analista envia datos nube','external ai provider consent metadata credentials openai privacy analyst sends data cloud',
  {sections:['AI Analyst']}),
 E('studio-what','¿Qué es Resurrection Studio?','What is Resurrection Studio?',
  'Un espacio para explorar el sistema reconstruido: buscar, navegar de cliente a ventas a detalle y editar una COPIA de trabajo con reglas de integridad. Por ejemplo, insertar una venta con un cliente inexistente se rechaza; con uno válido se acepta en la copia. Puedes exportar un prototipo HTML de solo consulta.',
  'A space to explore the reconstructed system: search, navigate from customer to sales to detail and edit a working COPY under integrity rules. For example, inserting a sale for a non-existent customer is rejected; with a valid one it is accepted in the copy. You can export a read-only HTML prototype.',
  'studio resurrection explorar buscar navegar editar crud insertar copia prototipo html reglas sistema reconstruido','studio resurrection explore search navigate edit crud insert copy prototype html rules reconstructed system',
  {sections:['Resurrection Studio'],follow:['studio-crud']}),
 E('studio-crud','¿Puedo modificar datos en el Studio?','Can I modify data in the Studio?',
  'Solo en una copia de trabajo en memoria, con reglas de integridad (p. ej., un cliente debe existir). El original y la evidencia no se tocan, y cada acción queda registrada. El prototipo exportado es de solo consulta.',
  'Only on an in-memory working copy, under integrity rules (e.g. a customer must exist). The original and the evidence are untouched, and every action is logged. The exported prototype is read-only.',
  'modificar editar insertar borrar crud copia trabajo reglas integridad cliente venta registrar studio','modify edit insert delete crud working copy rules integrity customer sale log studio',
  {sections:['Resurrection Studio']}),
 E('vault-what','¿Qué es Evidence Vault?','What is Evidence Vault?',
  'Genera el expediente verificable del trabajo: hashes, historial, incertidumbre, versiones y reglas. Pulsa «Generar expediente»; verás «Integridad verificada» si el hash propio coincide. Puedes descargar el expediente JSON y los informes en Markdown y HTML.',
  'It produces the verifiable dossier of the work: hashes, history, uncertainty, versions and rules. Press “Generar expediente”; you will see “Integridad verificada” if its own hash matches. You can download the JSON dossier and the Markdown and HTML reports.',
  'vault evidence expediente evidencia hashes historial informe integridad verificada generar dossier forense','vault evidence dossier hashes history report integrity verified generate forensic',
  {sections:['Evidence Vault'],follow:['vault-integrity']}),
 E('vault-integrity','¿Qué significa «Integridad verificada»?','What does “Integridad verificada” mean?',
  'Que el hash del propio expediente coincide con su contenido: si alguien lo modifica, deja de coincidir. No es una certificación forense ni garantiza que los datos originales fueran completos; solo demuestra que el expediente no cambió desde que se generó.',
  'That the dossier’s own hash matches its content: if anyone edits it, it stops matching. It is not a forensic certification and does not guarantee the original data was complete; it only shows the dossier did not change since it was generated.',
  'integridad verificada hash expediente forense certificacion manipulado modificado confiable','integrity verified hash dossier forensic certification tampered modified trustworthy',
  {sections:['Evidence Vault']}),
 E('filerec-what','¿Qué hace File Recovery?','What does File Recovery do?',
  'Analiza archivos sueltos: PNG, JPEG, PDF, ZIP/DOCX/XLSX y TXT. Identifica por firma, diagnostica la integridad, extrae lo verificable, registra los daños con rangos de bytes y exporta un informe JSON o un ZIP seguro. Con una imagen de disco en bruto busca archivos incrustados (carving).\nUsa «Cargar fixtures SINTÉTICOS» para probarlo.',
  'It analyses individual files: PNG, JPEG, PDF, ZIP/DOCX/XLSX and TXT. It identifies by signature, diagnoses integrity, extracts what can be verified, logs damage with byte ranges and exports a JSON report or a safe ZIP. With a raw disk image it looks for embedded files (carving).\nUse “Cargar fixtures SINTÉTICOS” to try it.',
  'file recovery archivos png jpeg pdf zip docx xlsx txt analizar integridad dañado reparar imagen disco carving informe','file recovery files png jpeg pdf zip docx xlsx txt analyse integrity damaged repair disk image carving report',
  {sections:['File Recovery'],follow:['carving','matrix']}),
 E('carving','¿Qué es el carving y por qué no es lo mismo que recuperar?','What is carving and why is it not the same as recovery?',
  'Carving es buscar firmas de archivos dentro de una imagen en bruto y cortar los trozos contiguos que parecen archivos. Puede dar falsos positivos, y los archivos fragmentados o sobrescritos no se pueden recuperar con este motor. Por eso un hallazgo por firma no se declara recuperación.',
  'Carving means searching for file signatures inside a raw image and cutting out contiguous chunks that look like files. It can give false positives, and fragmented or overwritten files cannot be recovered with this engine. That is why a signature hit is not declared a recovery.',
  'carving tallado firmas imagen disco bruto falso positivo fragmentado sobrescrito eliminado forense','carving signatures raw disk image false positive fragmented overwritten deleted forensic',
  {sections:['File Recovery']}),
 E('matrix','¿Qué es la matriz de capacidades?','What is the capability matrix?',
  'Es una tabla dentro de File Recovery que muestra, por tipo de archivo, qué está implementado y probado, qué es parcial y qué no existe aún. Se verifica con pruebas automáticas para que no afirme más de lo que hay.',
  'It is a table inside File Recovery showing, per file type, what is implemented and tested, what is partial and what does not exist yet. Automated tests check it so it never claims more than what exists.',
  'matriz capacidades implementado parcial no implementado tabla soporte formatos alcance','matrix capabilities implemented partial not implemented table support formats scope',
  {sections:['File Recovery']}),
 E('software-archaeology','¿Qué es Software Archaeology?','What is Software Archaeology?',
  'Es, por ahora, solo un diseño (pestaña dentro de File Recovery): cómo identificar programas heredados sin ejecutarlos. No recupera código fuente ni reconstruye aplicaciones desde binarios; esas capacidades no están implementadas.',
  'For now it is only a design (a tab inside File Recovery): how to identify legacy programs without running them. It does not recover source code or rebuild applications from binaries; those capabilities are not implemented.',
  'software archaeology arqueologia programas binarios ejecutables codigo fuente reconstruir aplicaciones','software archaeology programs binaries executables source code rebuild applications',
  {sections:['File Recovery']}),
];

